"""AI-assisted vector diagrams for Problem 2; Python standard library only.

Run this file to regenerate the two TikZ inputs next to it. Dipole contours
are sampled at 720 angles, with their radii determined by bisection.
"""

from math import cos, hypot, pi, sin, sqrt
from pathlib import Path


HERE = Path(__file__).resolve().parent


def point(x, y):
    return f"({x:.5f},{y:.5f})"


def spring():
    lines = [
        "% AI-assisted illustration, generated by generate_equipotentials.py.",
        r"\begin{tikzpicture}[>=stealth, font=\small, line width=0.6pt]",
        r"\node at (0,2.95) {Spherical equipotentials};",
        r"\node at (6.25,2.95) {Section at $z=0$};",
    ]
    # Translucent ball shading supplies the spherical surfaces. Draw all
    # surfaces before the wireframes so nested shell outlines remain clear.
    for j in reversed(range(6)):
        radius = sqrt(j + 1)
        lines.append(
            rf"\shade[ball color=cyan!{40 + 6*j}!blue,opacity=0.10] (0,0) circle ({radius:.5f});"
        )
    for j in range(6):
        radius = sqrt(j + 1)
        color = f"blue!{35 + 10*j}!black"
        lines += [
            rf"\draw[{color}] (0,0) circle ({radius:.5f});",
            rf"\draw[{color}, densely dashed, opacity=0.55] (0,0) ellipse ({radius:.5f} and {0.32*radius:.5f});",
            rf"\draw[{color}] (-{radius:.5f},0) arc[start angle=180,end angle=360,x radius={radius:.5f},y radius={0.32*radius:.5f}];",
            rf"\draw[{color}] (6.25,0) circle ({radius:.5f});",
        ]
        if j in (0, 2, 5):
            lines.append(rf"\draw[{color}, opacity=0.4] (0,0) ellipse ({0.32*radius:.5f} and {radius:.5f});")
    lines += [
        r"\fill (0,0) circle (0.035);",
        r"\node[below right] at (0,0) {$O$};",
        r"\draw[->,gray!65] (3.55,0) -- (8.95,0) node[right] {$x$};",
        r"\draw[->,gray!65] (6.25,-2.65) -- (6.25,2.65) node[above] {$y$};",
        r"\fill (6.25,0) circle (0.035);",
        r"\node[below right] at (6.25,0) {$O$};",
    ]
    # A common multiplier makes these arrow lengths proportional to |grad U|=r.
    for radius in (0.65, 1.35, 2.05):
        theta = pi / 4
        start = (6.25 + radius*cos(theta), radius*sin(theta))
        end_radius = 1.23 * radius
        end = (6.25 + end_radius*cos(theta), end_radius*sin(theta))
        lines.append(rf"\draw[->,orange!85!black,line width=1.1pt] {point(*start)} -- {point(*end)};")
    lines += [
        r"\node[fill=white,inner sep=2pt] at (7.35,2.32) {$\nabla U$};",
        r"\node at (0,-2.95) {Equal potential increments};",
        r"\node at (6.25,-2.95) {Arrow length $\propto |\nabla U|$};",
        r"\end{tikzpicture}",
    ]
    (HERE / "spring-equipotentials.tikz").write_text("\n".join(lines) + "\n")


def potential(x, y):
    return 1 / hypot(x, y) - 1 / hypot(x - 1, y)


def contour_radius(theta, level):
    # On the V>0 part of any ray from the origin, V decreases strictly.
    # The solution is below 1/level and, for cos(theta)>0, below x=1/2.
    lower = 1e-10
    upper = 1 / level
    if cos(theta) > 0:
        upper = min(upper, 0.5 / cos(theta))
    for _ in range(50):
        mid = (lower + upper) / 2
        if potential(mid*cos(theta), mid*sin(theta)) > level:
            lower = mid
        else:
            upper = mid
    return (lower + upper) / 2


def dipole():
    lines = [
        "% AI-assisted numerical contours, generated by generate_equipotentials.py.",
        r"\begin{tikzpicture}[x=2.5cm,y=2.5cm,>=stealth,font=\small]",
        r"\draw[gray!40] (-1.85,-1.55) rectangle (2.85,1.55);",
        r"\begin{scope}",
        r"\clip (-1.85,-1.55) rectangle (2.85,1.55);",
        r"\draw[->,gray!60] (-1.85,0) -- (2.81,0);",
        r"\draw[->,gray!60] (0,-1.55) -- (0,1.51);",
    ]
    max_residual = 0.0
    for i in range(1, 11):
        level = i / 4
        points = []
        for j in range(720):
            theta = 2*pi*j/720
            radius = contour_radius(theta, level)
            x, y = radius*cos(theta), radius*sin(theta)
            points.append((x, y))
            max_residual = max(max_residual, abs(potential(x, y) - level))
        for sign, color in ((1, "red!75!black"), (-1, "blue!75!black")):
            coords = points if sign == 1 else [(1-x, y) for x, y in points]
            lines.append(rf"\draw[{color},line width=0.65pt] " + " -- ".join(point(x, y) for x, y in coords) + " -- cycle;")
    lines.append(r"\draw[black,dashed,line width=0.75pt] (0.5,-1.55) -- (0.5,1.55);")
    # Equal-length arrows indicate direction. Equal potential increments convey
    # the varying gradient magnitude without compressing the force scale.
    arrow_count = 0
    force_lines = []
    for ix in range(14):
        x = -1.65 + 0.33*ix
        for iy in range(9):
            y = -1.32 + 0.33*iy
            r1, r2 = hypot(x, y), hypot(x-1, y)
            if min(r1, r2) < 0.23:
                continue
            fx = x/r1**3 - (x-1)/r2**3
            fy = y/r1**3 - y/r2**3
            magnitude = hypot(fx, fy)
            dx, dy = 0.07*fx/magnitude, 0.07*fy/magnitude
            force_lines.append(rf"\draw[->,black!55,line width=0.5pt] {point(x-dx,y-dy)} -- {point(x+dx,y+dy)};")
            arrow_count += 1
    lines[7:7] = force_lines
    lines += [
        r"\fill[white] (0,0) circle (0.065);",
        r"\fill[white] (1,0) circle (0.065);",
        r"\fill[red!75!black] (0,0) circle (0.035);",
        r"\fill[blue!75!black] (1,0) circle (0.035);",
        r"\node[below,fill=white,inner sep=1pt] at (0,-0.055) {$(0,0)$};",
        r"\node[below,fill=white,inner sep=1pt] at (1,-0.055) {$(1,0)$};",
        r"\node[fill=white,inner sep=2pt] at (0.5,1.4) {$V=0$};",
        r"\end{scope}",
        r"\node[right] at (2.85,0) {$x$};",
        r"\node[above] at (0,1.55) {$y$};",
        r"\node at (0.5,1.78) {$V=1/r_1-1/r_2$, $z=0$};",
        r"\node[align=center] at (0.5,-1.78) {Red: $V>0$, blue: $V<0$\\Arrows: direction of $\mathbf F=-\nabla V$};",
        r"\end{tikzpicture}",
    ]
    (HERE / "dipole-equipotentials.tikz").write_text("\n".join(lines) + "\n")
    print(f"Dipole: 20 contours, {arrow_count} force arrows; maximum level residual {max_residual:.2e}.")


if __name__ == "__main__":
    spring()
    dipole()
